    String content = "{\"id\":1,\"title\":\"Wprowadzenie do REST\"}";
    String etag = "\"" + Integer.toHexString(content.hashCode()) + "\""; // uproszczony "hash"
    exchange.getResponseHeaders().add("ETag", etag);
    respond(exchange, 200, content);
});

server.createContext("/articles/1", exchange -> {
    String currentEtag = "\"abc123\"";
    String clientEtag = exchange.getRequestHeaders().getFirst("If-None-Match");
    if (currentEtag.equals(clientEtag)) {
        exchange.getResponseHeaders().add("ETag", currentEtag);
        exchange.sendResponseHeaders(304, -1); // BEZ ciala - klient juz ma aktualna wersje
    } else {
        exchange.getResponseHeaders().add("ETag", currentEtag);
        respond(exchange, 200, "{\"id\":1,\"title\":\"Wprowadzenie do REST\"}");
    }
});

// ZLE: PUT bezwarunkowo nadpisuje zasob, bez wzgledu na to, czy ktos inny go zmienil
server.createContext("/articles/1", exchange -> {
    if (exchange.getRequestMethod().equals("PUT")) {
        String newContent = new String(exchange.getRequestBody().readAllBytes());
        saveArticle(1, newContent); // NADPISUJE bez sprawdzenia wersji - mozliwa utrata cudzej zmiany
        respond(exchange, 200, newContent);
    }
});

// DOBRZE: PUT wymaga If-Match, odrzuca nieaktualne wersje
server.createContext("/articles/1", exchange -> {
    if (exchange.getRequestMethod().equals("PUT")) {
        String clientEtag = exchange.getRequestHeaders().getFirst("If-Match");
        String currentEtag = "\"abc123\"";
        if (!currentEtag.equals(clientEtag)) {
            exchange.sendResponseHeaders(412, -1); // ktos inny juz zmienil zasob w miedzyczasie
            return;
        }
        String newContent = new String(exchange.getRequestBody().readAllBytes());
        saveArticle(1, newContent); // bezpieczne - wersja byla aktualna
        respond(exchange, 200, newContent);
    }
});
